# Frozen copy of the production-entry role policy, so existing businesses get
# their roles and permission rows at migrate time (the runtime seeder would
# otherwise only repair them the next time roles are touched).
MODULES = [
    "dashboard", "inventory", "procurement", "production", "sales", "expenses", "finance",
    "reports", "users", "commerce", "delivery", "delivery_rider", "kitchen", "audit", "pos",
]
KITCHEN_ROLES = {
    # key: (is_guided, {module: (can_view, can_edit)})
    "kitchen_cook": (False, {"kitchen": (True, True), "inventory": (True, False)}),
    "kitchen_guided": (True, {"kitchen": (True, True)}),
}
VERTICAL_ROLE_NAME = {"bakery": "Baker", "restaurant": "Chef", "general": "Production Staff"}
FULL_ACCESS_ROLE_KEYS = ("business_admin", "superuser", "live_tester")


def seed_kitchen_roles(apps, schema_editor):
    Business = apps.get_model("core", "Business")
    Role = apps.get_model("accounts", "Role")
    RoleModulePermission = apps.get_model("accounts", "RoleModulePermission")

    for business in Business.objects.all().iterator():
        base_name = VERTICAL_ROLE_NAME.get(business.vertical)
        if base_name:  # stock-first verticals (wholesale/retail) get no kitchen roles
            for key, (guided, grants) in KITCHEN_ROLES.items():
                role = Role.objects.filter(business=business, key=key).first()
                if role is None:
                    name = f"{base_name} (Guided)" if guided else base_name
                    # Never collide with a custom role the business already named this way.
                    if Role.objects.filter(business=business, name__iexact=name).exists():
                        name = f"{name} (system)"
                    role = Role.objects.create(
                        business=business, key=key, name=name, is_system=True, active=True, visible_to_admin=True,
                    )
                for module in MODULES:
                    can_view, can_edit = grants.get(module, (False, False))
                    RoleModulePermission.objects.get_or_create(
                        role=role, module=module, defaults={"can_view": can_view, "can_edit": can_edit},
                    )
        # Every other role keeps its access untouched; oversight roles get the
        # new module, everyone else starts with none.
        for role in Role.objects.filter(business=business).exclude(key__in=list(KITCHEN_ROLES)):
            full = role.key in FULL_ACCESS_ROLE_KEYS
            RoleModulePermission.objects.get_or_create(
                role=role, module="kitchen", defaults={"can_view": full, "can_edit": full},
            )


